class Solution:
    def thousandSeparator(self, n: int) -> str:
        if n == 0:
            return "0"
        result = ""
        count = 0
        for digit in str(n)[::-1]:
            if count == 3:
                result += "."
                count = 1
            else:
                count += 1
            result += digit
        return result[::-1]
