def pascal(p):
    if p == 0:
        return []
    elif p == 1:
        return [[1]]

    triangle = [[1]]

    for i in range(1, p):
        prev_row = triangle[i-1]
        new_row = [1]

        for j in range(1, i):
            new_row.append(prev_row[j-1] + prev_row[j])

        new_row.append(1)
        triangle.append(new_row)

    return triangle
```

