def pascal(p):
    if p == 0:
        return []
    elif p == 1:
        return [[1]]

    triangle = [[1]]

    for i in range(1, p):
        row = [1]
        for j in range(1, i):
            row.append(triangle[i-1][j-1] + triangle[i-1][j])
        row.append(1)
        triangle.append(row)

    return triangle
